using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using MC2Pack;
namespace Astera {
public sealed class FtlAuditFixture {public string AuditRoot,Source;public bool GeneratedGibs,RenegadeCollection;public Dictionary<string,string> Assets;}
static class MultiverseAudit {
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateHardLink(string target,string source,IntPtr unused);
    static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Assert(rejected,message);}
    static void Big(BinaryWriter writer,uint value){writer.Write(new[]{(byte)(value>>24),(byte)(value>>16),(byte)(value>>8),(byte)value});}
    static void Pkg(string path,bool modded){var names=modded?new[]{"data/blueprints.xml","data/hyperspace.xml"}:new[]{"data/blueprints.xml"};byte[] paths=Encoding.ASCII.GetBytes(String.Join("\0",names)+"\0");using(var f=File.Create(path))using(var w=new BinaryWriter(f)){w.Write(Encoding.ASCII.GetBytes("PKG\n"));w.Write(new byte[]{0,16,0,20});Big(w,(uint)names.Length);Big(w,(uint)paths.Length);int offset=0;for(int i=0;i<names.Length;i++){Big(w,0);Big(w,(uint)offset);Big(w,(uint)(16+20*names.Length+paths.Length+i));Big(w,1);Big(w,1);offset+=names[i].Length+1;}w.Write(paths);for(int i=0;i<names.Length;i++)w.Write((byte)1);}}
    static FtlPlan FixturePlan(string root,string work,string stage){return new FtlPlan{Root=root,Workspace=work,Stage=stage,DataVersion="5.5.1",AssetsVersion="5.5",HyperspaceVersion="1.23.2",Guards=new Dictionary<string,string>{{"ftl.dat",Engine.Hash(Path.Combine(root,"ftl.dat"))},{"FTLGame.exe",Engine.Hash(Path.Combine(root,"FTLGame.exe"))},{Multiverse.Marker,null}},Candidate=Directory.GetFiles(stage).ToDictionary(Path.GetFileName,Engine.Hash)};}
    internal static int SelfTest(string directory){var checks=new List<string>();try{
        directory=Engine.Root(directory);if(Directory.Exists(directory))throw new Exception("Use a new test directory");Directory.CreateDirectory(directory);string root=Path.Combine(directory,"FTL game"),work=Path.Combine(directory,"work"),stage=Path.Combine(work,"staging","fixture");Directory.CreateDirectory(root);Directory.CreateDirectory(stage);
        File.WriteAllBytes(Path.Combine(root,"FTLGame.exe"),new byte[]{77,90,1,2});Pkg(Path.Combine(root,"ftl.dat"),false);File.WriteAllText(Path.Combine(root,"carl-notes.txt"),"personal file");File.WriteAllText(Path.Combine(root,"example.sav"),"personal save fixture");
        var original=Directory.GetFiles(root).ToDictionary(Path.GetFileName,Engine.Hash);File.WriteAllBytes(Path.Combine(stage,"FTLGame.exe"),new byte[]{77,90,3,4});Pkg(Path.Combine(stage,"ftl.dat"),true);File.WriteAllBytes(Path.Combine(stage,"Hyperspace.dll"),new byte[]{77,90,5,6});File.WriteAllBytes(Path.Combine(stage,"xinput1_4.dll"),new byte[]{77,90,7,8});
        Multiverse.ValidateRoot(root);Assert(Multiverse.ArchiveNames(Path.Combine(stage,"ftl.dat")).Contains("data/hyperspace.xml"),"Archive index parser lost required paths");checks.Add("Valid FTL SIL indexes and required mod paths recognised without extraction");
        Reject(()=>Multiverse.Apply(FixturePlan(root,work,stage),s=>{},2),"Injected commit did not fail");foreach(var item in original)Assert(Engine.Hash(Path.Combine(root,item.Key))==item.Value,"Rollback changed original files");Assert(!File.Exists(Path.Combine(root,"Hyperspace.dll"))&&!File.Exists(Path.Combine(root,Multiverse.Marker)),"Rollback left new files or marker");checks.Add("Injected mid-install failure restores original files and removes newly created payloads");
        var plan=FixturePlan(root,work,stage);string backup=Multiverse.Apply(plan,s=>{});Assert(Multiverse.State(root).DataVersion=="5.5.1","Install record missing");Assert(Engine.Hash(Path.Combine(root,"carl-notes.txt"))==original["carl-notes.txt"]&&Engine.Hash(Path.Combine(root,"example.sav"))==original["example.sav"],"Unrelated files changed");checks.Add("Install writes managed files/record and preserves saves and unrelated files");
        File.AppendAllText(Path.Combine(root,"Hyperspace.dll"),"external change");string altered=Engine.Hash(Path.Combine(root,"Hyperspace.dll"));Reject(()=>Multiverse.Restore(root,work,s=>{}),"Restore overwrote an externally changed file");Assert(Engine.Hash(Path.Combine(root,"Hyperspace.dll"))==altered,"Changed file was not preserved");File.Copy(Path.Combine(stage,"Hyperspace.dll"),Path.Combine(root,"Hyperspace.dll"),true);checks.Add("Externally changed managed files stop restore without overwriting them");
        Multiverse.Restore(root,work,s=>{});foreach(var item in original)Assert(Engine.Hash(Path.Combine(root,item.Key))==item.Value,"Restore changed original bytes");Assert(!File.Exists(Path.Combine(root,"Hyperspace.dll"))&&!File.Exists(Path.Combine(root,Multiverse.Marker)),"Restore did not remove introduced files");checks.Add("Normal restore returns the prior installation byte-for-byte");
        plan=FixturePlan(root,work,stage);File.AppendAllText(Path.Combine(root,"FTLGame.exe"),"stale");Reject(()=>Multiverse.Apply(plan,s=>{}),"Stale install guards were ignored");File.WriteAllBytes(Path.Combine(root,"FTLGame.exe"),new byte[]{77,90,1,2});checks.Add("Changed installation invalidates a previously prepared plan");
        plan=FixturePlan(root,work,stage);string interrupted=Path.Combine(work,"backups","interrupted");Directory.CreateDirectory(interrupted);var journal=new FtlJournal{Root=root,Status="prepared"};foreach(var item in plan.Candidate){bool exists=File.Exists(Path.Combine(root,item.Key));string before=exists?Engine.Hash(Path.Combine(root,item.Key)):null;if(exists)File.Copy(Path.Combine(root,item.Key),Path.Combine(interrupted,item.Key));journal.Files.Add(new FtlFile{Name=item.Key,Before=before,After=item.Value,Existed=exists});}Multiverse.WriteJson(Path.Combine(interrupted,"transaction.json"),journal);File.Copy(Path.Combine(stage,"ftl.dat"),Path.Combine(root,"ftl.dat"),true);File.Copy(Path.Combine(stage,"Hyperspace.dll"),Path.Combine(root,"Hyperspace.dll"));Multiverse.Recover(root,work,s=>{});foreach(var item in original)Assert(Engine.Hash(Path.Combine(root,item.Key))==item.Value,"Interrupted recovery changed original files");Assert(Multiverse.Pending(root,work)==null&&!File.Exists(Path.Combine(root,"Hyperspace.dll")),"Interrupted recovery did not settle");checks.Add("Restart recovery recognises mixed before/after state and restores it safely");
        string corrupt=Path.Combine(directory,"invalid.dat");File.WriteAllBytes(corrupt,Encoding.ASCII.GetBytes("PKG\ninvalid"));Reject(()=>Multiverse.ArchiveNames(corrupt),"Malformed archive was accepted");checks.Add("Malformed archive indexes rejected");
        var cancelled=new CancellationToken(true);Reject(()=>Multiverse.Fetch(FixturePlan(root,work,stage),cancelled,s=>{}),"Cancellation was ignored");checks.Add("Cancelled work stops before modifying an installation");
        Assert(Multiverse.Quote("C:\\path with spaces\\").EndsWith("\\\\\""),"Windows argument quoting lost trailing backslash");checks.Add("Process arguments preserve spaces and trailing backslashes");
        checks.AddRange(MultiverseTrcAudit.Run());checks.AddRange(MultiverseContentAudit.Run(Path.Combine(directory,"content")));File.WriteAllText(Path.Combine(directory,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,LiveGamesChanged=false,GameExecutableRun=false}));return 0;
    }catch(Exception error){Directory.CreateDirectory(directory);File.WriteAllText(Path.Combine(directory,"failure.txt"),error.ToString());return 1;}}
    internal static int RealTest(string fixtureFile){FtlAuditFixture fixture=Engine.Json.Deserialize<FtlAuditFixture>(File.ReadAllText(fixtureFile));string audit=Engine.Root(fixture.AuditRoot);try{
        if(!audit.Replace('\\','/').StartsWith("D:/vale/StarsAllies-Storage/audits/ftl-",StringComparison.OrdinalIgnoreCase)||Directory.Exists(audit))throw new Exception("Real patch audit must use a new approved D: audit directory");Directory.CreateDirectory(audit);string root=Path.Combine(audit,"FTL game"),work=Path.Combine(audit,"workspace");Directory.CreateDirectory(root);
        var before=new Dictionary<string,string>();foreach(var name in new[]{"FTLGame.exe","ftl.dat"}){string source=Path.Combine(fixture.Source,name);before[name]=Engine.Hash(source);File.Copy(source,Path.Combine(root,name));}File.WriteAllText(Path.Combine(root,"carl-personal.txt"),"preserve this file");var plan=Multiverse.Check(root,work,CancellationToken.None);Multiverse.SelectGibs(plan,fixture.GeneratedGibs);Multiverse.SelectTrc(plan,fixture.RenegadeCollection);Directory.CreateDirectory(Path.Combine(work,"downloads"));
        foreach(var asset in Multiverse.Payloads(plan)){string source=fixture.Assets[asset.Name];Assert(new FileInfo(source).Length==asset.Size,"Fixture asset size mismatch");string hash=Engine.Hash(source);if(asset.Sha256!=null)Assert(hash.Equals(asset.Sha256,StringComparison.OrdinalIgnoreCase),"Fixture asset upstream digest mismatch");string key=Engine.Hash(Encoding.UTF8.GetBytes(asset.Url+"\n"+asset.Id)),cache=Path.Combine(work,"downloads",key+".bin");if(!CreateHardLink(cache,source,IntPtr.Zero))File.Copy(source,cache);Multiverse.WriteJson(cache+".json",new Dictionary<string,string>{{"Url",asset.Url},{"Sha256",hash}});}
        using(var log=new StreamWriter(Path.Combine(audit,"operations.log"))){Action<string> write=s=>{log.WriteLine(s);log.Flush();};Multiverse.Fetch(plan,CancellationToken.None,write);Multiverse.Prepare(plan,CancellationToken.None,write);var staged=plan.Candidate.ToDictionary(p=>p.Key,p=>p.Value);int entries=Multiverse.ArchiveNames(Path.Combine(plan.Stage,"ftl.dat")).Count;string backup=Multiverse.Apply(plan,write);Assert(Multiverse.State(root)!=null&&Multiverse.State(root).GibsVersion==plan.GibsVersion&&Multiverse.State(root).TrcVersion==plan.TrcVersion&&Multiverse.State(root).TrcGibsVersion==plan.TrcGibsVersion,"Actual installation marker/addon version missing");string originalBackup=Multiverse.State(root).OriginalBackup;foreach(var item in staged)Assert(Engine.Hash(Path.Combine(root,item.Key))==item.Value,"Actual installed file differs from staging");
            // Reinstall/update uses the untouched original base, never the already patched DAT.
            var update=Multiverse.Check(root,work,CancellationToken.None);Multiverse.SelectGibs(update,fixture.GeneratedGibs);Multiverse.SelectTrc(update,fixture.RenegadeCollection);update.Downloads=plan.Downloads;Multiverse.Prepare(update,CancellationToken.None,write);Multiverse.Apply(update,write);if(fixture.RenegadeCollection){var off=Multiverse.Check(root,work,CancellationToken.None);Multiverse.SelectGibs(off,fixture.GeneratedGibs);Multiverse.SelectTrc(off,false);off.Downloads=plan.Downloads.Where(p=>Multiverse.Payloads(off).Any(a=>a.Name==p.Key)).ToDictionary(p=>p.Key,p=>p.Value);Multiverse.Prepare(off,CancellationToken.None,write);Multiverse.Apply(off,write);Assert(Multiverse.State(root).TrcVersion==null&&Multiverse.State(root).TrcGibsVersion==null,"Disabled TRC remained installed");Multiverse.Restore(root,work,write);Assert(Multiverse.State(root).TrcVersion=="2.6","TRC removal rollback did not restore its selected state");}Assert(Multiverse.State(root).OriginalBackup==originalBackup,"Original backup linkage missing");Multiverse.Restore(root,work,write);Multiverse.Restore(root,work,write);
            foreach(var item in before){Assert(Engine.Hash(Path.Combine(root,item.Key))==item.Value,"Actual restore did not recover original bytes");Assert(Engine.Hash(Path.Combine(fixture.Source,item.Key))==item.Value,"Source game was changed");}Assert(File.ReadAllText(Path.Combine(root,"carl-personal.txt"))=="preserve this file","Personal file changed");
            File.WriteAllText(Path.Combine(audit,"result.json"),Engine.Json.Serialize(new{Passed=true,Data=plan.DataVersion,Assets=plan.AssetsVersion,Hyperspace=plan.HyperspaceVersion,GeneratedGibs=plan.GibsVersion,RenegadeCollection=plan.TrcVersion,TrcGeneratedGibs=plan.TrcGibsVersion,OptionalTrcRemovalAndRestore=fixture.RenegadeCollection,StagedEntries=entries,CandidateHashes=staged,InitialInstall=true,UpdateFromVanillaBase=true,TwoRestoresRecoveredOriginal=true,SourceUnchanged=true,GameExecutableRun=false,PatchedGameBootVerified=false}));
        }return 0;
    }catch(Exception error){Directory.CreateDirectory(audit);File.WriteAllText(Path.Combine(audit,"failure.txt"),error.ToString());return 1;}}
}
